struct Trie {
    Trie* child[26] = {};
    bool end = false;
    void insert(const string& w) {
        Trie* node = this;
        for (char c : w) {
            int k = c - 'a';
            if (!node->child[k]) node->child[k] = new Trie();
            node = node->child[k];
        }
        node->end = true;
    }
    bool search(const string& w, bool prefix=false) {
        Trie* node = this;
        for (char c : w) {
            int k = c - 'a';
            if (!node->child[k]) return false;
            node = node->child[k];
        }
        return prefix || node->end;
    }
};

class Trie:
    def __init__(self):
        self.child = {}
        self.end = False
    def insert(self, w):
        node = self
        for c in w:
            node = node.child.setdefault(c, Trie())
        node.end = True
    def search(self, w, prefix=False):
        node = self
        for c in w:
            if c not in node.child:
                return False
            node = node.child[c]
        return prefix or node.end
